class ScalingLawModel:
    """Compact scaling law with per-group fitting, Expert-B form, and cross-term variation."""

    def __init__(s, b, n=None, c=None):
        s.benchmark_name = b
        s.numeric_names = list(n or [])
        s.categorical_names = list(c or [])
        s.p_ = {}
        s.d_ = None
        s.num_features_ = len(s.numeric_names)

    def fit(s, X_num, X_cat, y):
        from scipy.optimize import least_squares
        import numpy as np
        X = np.asarray(X_num, float)
        y = np.asarray(y, float)
        L = group_labels(X_cat)

        def _fg(Xg, yg):
            bn = s.benchmark_name
            if bn == "sld-vocab":
                def pred(X, p):
                    n, v, d = np.maximum(X[:, 0], 1), np.maximum(X[:, 1], 1), np.maximum(X[:, 2], 1)
                    return p[0] + p[1] * n ** -p[2] + p[3] * v ** -p[4] + p[5] * d ** -p[6] + p[7] * v ** -p[8] * d ** -p[9]
                def unpack(u):
                    return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), np.exp(u[4]), np.exp(u[5]), np.exp(u[6]), np.exp(u[7]), np.exp(u[8]), np.exp(u[9])])
                ys = max(float(yg.max() - yg.min()), 0.1)
                init = np.array([float(np.median(yg)), np.log(ys), np.log(0.08), np.log(ys), np.log(0.3), np.log(ys), np.log(0.3), np.log(ys * 0.5), np.log(0.3), np.log(0.3)])
            elif bn == "sld-lrbsz":
                def pred(X, p):
                    lr = np.maximum(X[:, 0], 1e-12)
                    bsz = np.maximum(X[:, 1], 1)
                    d = np.maximum(X[:, 2], 1)
                    n = np.maximum(X[:, 3], 1)
                    A, a, B, b, C, D_lr, E, F, g, z, G, et = p
                    l0 = F * n ** g * d ** z
                    b0 = G * d ** et
                    return A * d ** -a + B * n ** -b + C + D_lr * (lr - l0) ** 2 + E * (np.log(bsz) + b0 / bsz)
                def unpack(u):
                    return np.array([np.exp(u[0]), np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), u[4], np.exp(u[5]), np.exp(u[6]), np.exp(u[7]), u[8], u[9], np.exp(u[10]), u[11]])
                init = np.array([np.log(262), np.log(0.27), np.log(7.0), np.log(0.075), 0.0, np.log(1279), np.log(0.05), np.log(0.32), -1.06, 0.65, np.log(0.03), 0.35])
            else:
                def pred(X, p):
                    u = np.maximum(X[:, 0], 1)
                    n = np.maximum(X[:, 1], 1)
                    d = np.maximum(X[:, 2], 1)
                    de = np.maximum(u * (1 - np.exp(-np.clip(d / u, 0, 50))), 1)
                    return p[0] + p[1] * n ** -p[2] + p[3] * de ** -p[4]
                def unpack(u):
                    return np.exp(u)
                ys = max(float(yg.max() - yg.min()), 0.1)
                init = np.array([np.log(max(yg.min() * 0.9, 0.1)), np.log(ys), np.log(0.35), np.log(ys), np.log(0.35)])

            def resid(u):
                try:
                    return (pred(Xg, unpack(u)) - yg).flatten()
                except Exception:
                    return np.full_like(yg, 1e3)

            rng = np.random.default_rng(0)
            best_u, best_s = init.copy(), float("inf")
            for _ in range(6):
                try:
                    r = least_squares(resid, init + rng.normal(scale=0.2, size=init.shape), method="trf", loss="soft_l1", f_scale=0.05, max_nfev=3000)
                    u0 = r.x
                except Exception:
                    u0 = init.copy()
                s_ = float(np.mean((pred(Xg, unpack(u0)) - yg) ** 2))
                if np.isfinite(s_) and s_ < best_s:
                    best_s, best_u = s_, u0
            return unpack(best_u)

        fitted = [_fg(X[L == g], y[L == g]) for g in sorted(set(L))]
        s.p_ = {g: fitted[i] for i, g in enumerate(sorted(set(L)))}
        s.d_ = np.median(np.stack(fitted, axis=0), axis=0) if fitted else None
        return s

    def predict(s, X_num, X_cat):
        import numpy as np
        X = np.asarray(X_num, float)
        L = group_labels(X_cat)
        r = np.zeros(len(L), float)
        bn = s.benchmark_name
        for g in sorted(set(L)):
            m = L == g
            p = s.p_.get(g, s.d_)
            if bn == "sld-vocab":
                n, v, d = np.maximum(X[m, 0], 1), np.maximum(X[m, 1], 1), np.maximum(X[m, 2], 1)
                r[m] = p[0] + p[1] * n ** -p[2] + p[3] * v ** -p[4] + p[5] * d ** -p[6] + p[7] * v ** -p[8] * d ** -p[9]
            elif bn == "sld-lrbsz":
                lr = np.maximum(X[m, 0], 1e-12)
                bsz = np.maximum(X[m, 1], 1)
                d = np.maximum(X[m, 2], 1)
                n = np.maximum(X[m, 3], 1)
                A, a, B, b, C, D_lr, E, F, g, z, G, et = p
                l0 = F * n ** g * d ** z
                b0 = G * d ** et
                r[m] = A * d ** -a + B * n ** -b + C + D_lr * (lr - l0) ** 2 + E * (np.log(bsz) + b0 / bsz)
            else:
                u = np.maximum(X[m, 0], 1)
                n = np.maximum(X[m, 1], 1)
                d = np.maximum(X[m, 2], 1)
                de = np.maximum(u * (1 - np.exp(-np.clip(d / u, 0, 50))), 1)
                r[m] = p[0] + p[1] * n ** -p[2] + p[3] * de ** -p[4]
        return r

